import json
from pathlib import Path
import sys
import tempfile
import unittest

from evaluate_original import ROOT, prepare, run


class OriginalEvaluationTests(unittest.TestCase):
    def test_preparation_preserves_specs_and_refuses_reuse(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "evaluation"
            prepare(output, "http://127.0.0.1:5173")
            for source in (ROOT / "input/tests").glob("*.ts"):
                self.assertEqual(source.read_bytes(), (output / "tests" / source.name).read_bytes())
            with self.assertRaises(FileExistsError):
                prepare(output, "http://127.0.0.1:5173")

    def test_failed_seed_blocks_all_scenarios(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "evaluation"
            prepare(output, "http://127.0.0.1:5173")
            self.assertEqual(run(output, [sys.executable, "-c", "raise SystemExit(7)"]), 1)
            summary = json.loads((output / "summary.json").read_text())
            self.assertEqual(summary["seed_exit_code"], 7)
            self.assertEqual(set(summary["scenarios"].values()), {"unexecuted"})
            self.assertFalse((output / "runner.log").exists())
            self.assertFalse(summary["accepted"])
            with self.assertRaises(ValueError):
                run(output, [sys.executable, "-c", "pass"])


if __name__ == "__main__":
    unittest.main()
